 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]
    boxes = {}
    counts = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        boxes[color] = (min(r for r, c in cells), min(c for r, c in cells),
                        max(r for r, c in cells), max(c for r, c in cells))
        counts[color] = len(cells)
    outer = max(colors, key=lambda col: counts[col])
    inner = next(col for col in colors if col != outer)
    r0, c0, r1, c1 = boxes[outer]
    ir0, ic0, ir1, ic1 = boxes[inner]
    # Build the bounding box one frame-width larger than the solid-color rectangle,
    # and paint only the blank extension in the inset color.
    t = min(ir0-r0, r1-ir1, ic0-c0, c1-ic1)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-t), min(h, r1+t+1)):
        for c in range(max(0, c0-t), min(w, c1+t+1)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out
