    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]
    boxes = {}
    counts = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        boxes[color] = (min(r for r, c in cells), min(c for r, c in cells),
                        max(r for r, c in cells), max(c for r, c in cells))
        counts[color] = len(cells)
    body = max(colors, key=lambda col: counts[col])
    marker = next(col for col in colors if col != body)
    r0, c0, r1, c1 = boxes[body]
    # Grow the body's rectangle by the thickness of its colored edge, capped by
    # half the marker's smaller dimension (the compact marker case grows one).
    mr0, mc0, mr1, mc1 = boxes[marker]
    thickness = min(mr0-r0, r1-mr1, mc0-c0, c1-mc1)
    marker_size = min(mr1-mr0+1, mc1-mc0+1)
    grow = min(thickness, max(1, marker_size//2))
    out = [row[:] for row in grid]
    for r in range(max(0, r0-grow), min(h, r1+grow+1)):
        for c in range(max(0, c0-grow), min(w, c1+grow+1)):
            if grid[r][c] == 0:
                out[r][c] = marker
    return out
