 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]
    bounds, counts = {}, {}
    for color in colors:
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        bounds[color] = (min(r for r,c in cells), min(c for r,c in cells), max(r for r,c in cells), max(c for r,c in cells))
        counts[color] = len(cells)
    outer = max(colors, key=lambda x: (bounds[x][2]-bounds[x][0]+1)*(bounds[x][3]-bounds[x][1]+1))
    inner = next(x for x in colors if x != outer)
    r0,c0,r1,c1 = bounds[outer]
    ir0,ic0,ir1,ic1 = bounds[inner]
    # Enlarge the overall patterned square by a margin derived from the inset.
    # The examples have one extra layer for a singleton and two for a region.
    grow = 1 if counts[inner] == 1 else 2
    out = [row[:] for row in grid]
    for r in range(max(0,r0-grow), min(h,r1+grow+1)):
        for c in range(max(0,c0-grow), min(w,c1+grow+1)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out
