 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]

    bounds = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        bounds[color] = (min(r for r, c in cells), min(c for r, c in cells),
                         max(r for r, c in cells), max(c for r, c in cells))

    # The larger rectangle is the framed object; the other color is copied into
    # a halo around it, with halo width/height matching that inner patch.
    outer = max(colors, key=lambda x: (bounds[x][2] - bounds[x][0] + 1) *
                                      (bounds[x][3] - bounds[x][1] + 1))
    inner = next(x for x in colors if x != outer)
    r0, c0, r1, c1 = bounds[outer]
    ir0, ic0, ir1, ic1 = bounds[inner]
    halo_h = ir1 - ir0 + 1
    halo_w = ic1 - ic0 + 1

    out = [row[:] for row in grid]
    for r in range(max(0, r0 - halo_h), min(h, r1 + halo_h + 1)):
        for c in range(max(0, c0 - halo_w), min(w, c1 + halo_w + 1)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out
"
}

